'use strict';
const CanvasStudio=(()=>{
  const M=FoldCanvasModel,svg=document.querySelector('#drawing');
  let api,scene,box,dragging,selection=null,zoom=1,signature='',pan={x:0,y:0};
  const el=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function view(){if(!box)return;const w=box.w/zoom,h=box.h/zoom;svg.setAttribute('viewBox',`${box.x+(box.w-w)/2+pan.x} ${box.y+(box.h-h)/2+pan.y} ${w} ${h}`);el('zoomLabel').textContent=zoom===1?'Fit':Math.round(zoom*100)+'%'}
  function fitView(){if(!scene)return;const b=api.layout.bounds(scene.g,scene.p,scene.fit)||M.bounds(scene.g,scene.p,scene.fit),pad=Math.max(b.w,b.h)*.11;box={x:b.x-pad,y:b.y-pad,w:b.w+2*pad,h:b.h+2*pad};pan={x:0,y:0};zoom=1;api.onZoom(1);view();paint()}
  function size(){return box?Math.max(box.w/Math.max(100,svg.clientWidth),box.h/Math.max(100,svg.clientHeight))/zoom:1}
  function paint(){if(!scene||!box)return;const {g,p,fit,t}=scene,u=size(),sw=fit.sheetW,sh=fit.sheetH,m=p.margin,rot=fit.rotate,arranging=api.layout.active();const sheetName=p.paper==='auto'?'AUTO':((Math.abs(sw-210)<.001&&Math.abs(sh-297)<.001)||(Math.abs(sw-297)<.001&&Math.abs(sh-210)<.001))?'A4':p.paper.toUpperCase();
    const transform=rot?`translate(${m+g.bh} ${m}) rotate(90)`:`translate(${m} ${m})`;
    const overall={key:'scale-all',label:'Scale entire design',x:g.bw,y:g.bh,axis:'both',sign:1};const handles=[overall];const handleMarkup=el('editHandles').checked&&!api.artwork.editing()&&!arranging?handles.map(h=>{const a=M.point([h.x,h.y],g,p,fit),active=h.key===selection,fields=FoldGeometry.fields(t.kind),limits=[...fields.main,...fields.extra].find(f=>f[0]===h.key);return `<g class="resize-handle ${h.key==='scale-all'?'scale-all-handle':''} ${active?'is-selected':''}" data-key="${h.key}" role="slider" tabindex="0" aria-label="Drag ${h.label}" aria-valuemin="${h.key==='scale-all'?1:api.display(limits[2])}" aria-valuemax="${h.key==='scale-all'?500:api.display(limits[3])}" aria-valuenow="${h.key==='scale-all'?100:api.display(p[h.key])}" aria-valuetext="${h.key==='scale-all'?'100% · all dimensions':api.display(p[h.key])+' '+api.unit()}" transform="translate(${a[0]} ${a[1]})"><title>${h.label}: ${h.key==='scale-all'?'drag corner to resize all dimensions together':api.display(p[h.key])+' '+api.unit()}. Drag or use arrow keys. Shift: 10 mm; Alt: 0.1 mm.</title><circle class="handle-hit" r="${17*u}" fill="transparent"/><circle class="handle-halo" r="${10*u}" fill="white" stroke="#c56a42" stroke-width="${1.1*u}"/><circle class="handle-dot" r="${5.5*u}" stroke-width="${1.5*u}"/><path d="M${-2*u} 0h${4*u}M0 ${-2*u}v${4*u}" stroke-width="${u}"/>${active?`<g class="handle-value" pointer-events="none"><rect x="${-33*u}" y="${-35*u}" width="${66*u}" height="${18*u}" rx="${7*u}"/><text text-anchor="middle" x="0" y="${-22*u}" font-size="${10*u}">${h.key==='scale-all'?'Whole design '+api.display(p.w)+' × '+api.display(p.h):esc(h.label)+' '+api.display(p[h.key])}</text></g>`:""}</g>`}).join(''):'';
    const grid=el('canvasGrid').checked?`<defs><pattern id="mmGrid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M10 0H0V10" fill="none" stroke="#e8ece3" stroke-width="${.6*u}"/></pattern></defs><rect width="${sw}" height="${sh}" fill="url(#mmGrid)" pointer-events="none"/>`:'';
    const dw=rot?g.bh:g.bw,dh=rot?g.bw:g.bh;
    const design=arranging?api.layout.markup(g,p,u,api.paths):`<g id="dielineScene" transform="${transform}">${api.paths(g)}${api.artwork.overlay(t,p,g,u)}</g>${el('showDimensions').checked?api.dimensions(g,rot):''}`;
    svg.innerHTML=`<g id="paperFrame" aria-label="${sheetName} paper ${sw} by ${sh} millimeters"><rect class="paper-sheet" width="${sw}" height="${sh}" fill="#fff" stroke="#bcc5b2" stroke-width="${u}"/>${grid}<rect x="${m}" y="${m}" width="${Math.max(0,sw-m*2)}" height="${Math.max(0,sh-m*2)}" fill="none" stroke="#bdc8af" stroke-width="${u}" stroke-dasharray="${4*u} ${4*u}"/><text x="0" y="${-9*u}" font-size="${11*u}" fill="#73816a" font-family="DM Sans,sans-serif">${sheetName} · ${api.display(sw)} × ${api.display(sh)} ${api.unit()}</text><text x="0" y="${sh+15*u}" font-size="${11*u}" fill="#8b9781" font-family="DM Sans,sans-serif">${api.display(m)} ${api.unit()} margin${rot?' · dieline rotated 90°':''}</text></g>${design}${!fit.fits&&!arranging?`<rect x="${m}" y="${m}" width="${dw}" height="${dh}" fill="none" stroke="#c95c35" stroke-width="${u}" stroke-dasharray="${5*u} ${3*u}" pointer-events="none"/>`:''}<g id="resizeHandles">${handleMarkup}</g>`;
    el('canvasPaper').value=p.paper;el('paperOrientation').disabled=p.paper==='auto';el('paperOrientation').textContent=sw>sh?'Landscape':'Portrait';el('canvasFitStatus').textContent=fit.fits?'Fits printable area':'Outside printable area';el('canvasFitStatus').classList.toggle('overflows',!fit.fits);el('canvasFitStatus').title=`Dieline ${api.display(g.bw)} × ${api.display(g.bh)} ${api.unit()}; sheet ${api.display(sw)} × ${api.display(sh)} ${api.unit()}`;
    if(arranging){el('canvasFitStatus').textContent=fit.fits?`${p.layout.items.length} ${p.layout.items.length===1?'copy':'copies'} · ready to print`:'Overlap or outside margins';el('canvasFitStatus').title='Copies keep actual size. Red outlines need rearranging.'}
    document.querySelector('.canvas-gesture-hint').textContent=arranging?'Drag copies · R rotate · Ctrl+D duplicate · scroll to zoom':api.artwork.editing()?'Background tool · click a component · drag images to position':'Drag corner to scale entire design · drag paper to pan · scroll to zoom';updateInspector();view();
  }
  function render(g,p,fit,t){scene={g,p:{...p},fit:dragging?.type==='resize'?{...fit,rotate:dragging.rotated}:fit,t};const nextSignature=[t.id,p.paper,p.paperW,p.paperH].join('|');if(!box||signature!==nextSignature){signature=nextSignature;fitView();return}paint()}
  function select(key){selection=key;paint();el('directValue').focus({preventScroll:true});el('directValue').select()}
  function updateInspector(){if(!scene)return;const h=M.handles(scene.t,scene.p,scene.g).find(h=>h.key===selection);el('directEditor').hidden=!h||api.layout.active();document.querySelectorAll('[data-param]').forEach(input=>input.closest('.field').classList.toggle('canvas-selected',input.dataset.param===selection));if(h){el('directLabel').textContent=h.label;el('directValue').value=api.display(scene.p[h.key]);el('directUnit').textContent=api.unit()}}
  function svgPoint(x,y,matrix=svg.getScreenCTM()?.inverse()){if(!matrix)return{x:0,y:0};return new DOMPoint(x,y).matrixTransform(matrix)}
  function setZoom(value){zoom=Math.max(.25,Math.min(6,value));view();paint();api.onZoom(zoom)}
  function end(event,cancel=false){if(!dragging)return;const d=dragging;dragging=null;svg.classList.remove('is-dragging');try{svg.releasePointerCapture(event.pointerId)}catch{}if(['resize','artwork','layout'].includes(d.type)){if(cancel)api.change(d.start);else api.commit(d.start);api.refresh()}else if(d.type==='pan'&&!d.moved){selection=null;paint()}}
  function init(config){api=config;svg.style.transform='none';
    el('canvas').insertAdjacentHTML('beforebegin',`<div class="canvas-tools"><div class="paper-tools"><label for="canvasPaper">Paper</label><select id="canvasPaper" aria-label="Canvas paper size"><option value="a4">A4 · 210 × 297</option><option value="a3">A3 · 297 × 420</option><option value="letter">Letter</option><option value="custom">Custom sheet</option><option value="auto">Auto size</option></select><button id="paperOrientation" title="Swap paper width and height">▯ Portrait</button><button id="fitA4" title="Scale every active dieline dimension down to fit the printable area. Changes can be undone.">Fit design</button><button id="fitPaper" title="Center paper and dieline without changing any dimensions" aria-label="Center paper">Center</button></div><div class="canvas-options"><label><input id="editHandles" type="checkbox" checked> Handles</label><label><input id="canvasGrid" type="checkbox"> 10 mm grid</label><label><input id="snapSize" type="checkbox" checked> Snap 1 mm</label><span id="canvasFitStatus" role="status"></span></div></div>`);
    el('canvas').insertAdjacentHTML('beforeend',`<form id="directEditor" hidden><div><label id="directLabel" for="directValue">Width</label><button type="button" id="closeDirect" aria-label="Close direct editor">×</button></div><div><input id="directValue" type="number" step="any" inputmode="decimal" aria-label="Direct dimension value"><span id="directUnit">mm</span><button type="submit" aria-label="Apply direct dimension">Apply</button></div></form><div class="canvas-gesture-hint">Drag a handle to resize · drag paper to pan · scroll to zoom</div>`);
    svg.addEventListener('pointerdown',event=>{if(event.button!==0&&event.button!==1||api.invalid())return;api.artwork.flush();const target=event.target.closest('[data-key]'),image=event.target.closest('[data-art-part]'),copy=event.target.closest('[data-layout-id]');const matrix=svg.getScreenCTM()?.inverse();if(!matrix)return;const at=svgPoint(event.clientX,event.clientY,matrix);if(copy&&api.layout.active()&&event.button===0){api.layout.select(copy.dataset.layoutId);dragging={type:'layout',pointer:event.pointerId,start:api.state(),matrix,at,id:copy.dataset.layoutId,moved:false}}else if(image&&api.artwork.editing()&&event.button===0){const id=image.dataset.artPart;api.artwork.select(id);if(!api.artwork.hasImage(id)){event.preventDefault();return}dragging={type:'artwork',pointer:event.pointerId,start:api.state(),matrix,at,part:id,rotated:scene.fit.rotate,moved:false}}else if(target&&event.button===0){selection=target.dataset.key;const h=selection==='scale-all'?{key:'scale-all',x:scene.g.bw,y:scene.g.bh,axis:'both'}:M.handles(scene.t,scene.p,scene.g).find(h=>h.key===selection);dragging={type:'resize',pointer:event.pointerId,start:api.state(),matrix,at,handle:h,initialBounds:{bw:scene.g.bw,bh:scene.g.bh},rotated:scene.fit.rotate,moved:false};paint()}else dragging={type:'pan',pointer:event.pointerId,matrix,at,pan:{...pan},moved:false};svg.setPointerCapture(event.pointerId);svg.classList.add('is-dragging');event.preventDefault()});
    svg.addEventListener('pointermove',event=>{if(!dragging||event.pointerId!==dragging.pointer)return;const d=dragging,at=svgPoint(event.clientX,event.clientY,d.matrix),dx=at.x-d.at.x,dy=at.y-d.at.y;d.moved=d.moved||Math.hypot(dx,dy)>.5;if(d.type==='pan'){pan={x:d.pan.x-dx,y:d.pan.y-dy};view();return}const snap=event.altKey?.1:el('snapSize').checked?1:0;if(d.type==='layout'){api.layout.drag(d.start,d.id,dx,dy,snap);return}const local=M.localDelta(dx,dy,d.rotated);if(d.type==='artwork'){api.artwork.drag(d.start,d.part,local[0],local[1]);return}if(d.handle.key==='scale-all'){const bw=d.initialBounds.bw,bh=d.initialBounds.bh,ratio=1+(local[0]*bw+local[1]*bh)/(bw*bw+bh*bh);api.change(M.scaleDrag(scene.t,d.start,ratio,snap));return}const delta=(d.handle.axis==='x'?local[0]:local[1])*d.handle.sign;api.change(M.drag(scene.t,d.start,d.handle.key,delta,snap))});
    svg.addEventListener('pointerup',e=>end(e));svg.addEventListener('pointercancel',e=>end(e,true));svg.addEventListener('lostpointercapture',e=>{if(dragging)end(e,true)});
    svg.addEventListener('wheel',event=>{if(!scene||!box)return;event.preventDefault();const before=svgPoint(event.clientX,event.clientY),image=event.target.closest('[data-art-part]');if(api.artwork.editing()&&image&&!event.ctrlKey){api.artwork.select(image.dataset.artPart);const local=scene.fit.rotate?{x:before.y-scene.p.margin,y:scene.g.bh-before.x+scene.p.margin}:{x:before.x-scene.p.margin,y:before.y-scene.p.margin};if(api.artwork.wheel(local,Math.exp(-event.deltaY*.0015)))return}setZoom(zoom*Math.exp(-event.deltaY*.0015));const after=svgPoint(event.clientX,event.clientY);pan.x+=before.x-after.x;pan.y+=before.y-after.y;view()},{passive:false});
    svg.addEventListener('dblclick',event=>{const copy=event.target.closest('[data-layout-id]');if(copy){api.layout.select(copy.dataset.layoutId);return}const image=event.target.closest('[data-art-part]');if(image){api.artwork.select(image.dataset.artPart);return}const target=event.target.closest('[data-key]');if(target)select(target.dataset.key);else fitView()});
    svg.addEventListener('keydown',event=>{const copy=event.target.closest('[data-layout-id]');if(copy&&api.layout.active()){const id=copy.dataset.layoutId;if(event.key==='Enter'){event.preventDefault();api.layout.select(id)}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();api.layout.select(id);const start=api.state(),step=event.altKey?.1:event.shiftKey?10:1;api.layout.drag(start,id,event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0,event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0,0);api.commit(start)}svg.querySelector(`[data-layout-id="${id}"]`)?.focus();return}const image=event.target.closest('[data-art-part]');if(image){const id=image.dataset.artPart;if(event.key==='Enter'){event.preventDefault();api.artwork.select(id);return}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)||!api.artwork.hasImage(id))return;event.preventDefault();api.artwork.select(id);const start=api.state(),step=event.altKey?.1:event.shiftKey?10:1;api.artwork.drag(start,id,event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0,event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0);api.commit(start);svg.querySelector(`[data-art-part="${id}"]`)?.focus();return}const target=event.target.closest('[data-key]');if(!target)return;const key=target.dataset.key;if(key==='scale-all'&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();const before=api.state(),step=event.shiftKey?10:1,sign=['ArrowLeft','ArrowDown'].includes(event.key)?-1:1;api.change(M.scaleDrag(scene.t,before,1+sign*step/before.w,0));api.commit(before);svg.querySelector('[data-key="scale-all"]')?.focus();return}if(event.key==='Enter'){event.preventDefault();select(key);return}if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;event.preventDefault();selection=key;const before=api.state(),delta=(event.key==='ArrowLeft'||event.key==='ArrowDown'?-1:1)*(event.altKey?.1:event.shiftKey?10:1);api.change(M.drag(scene.t,before,key,delta,0));api.commit(before);svg.querySelector(`[data-key="${key}"]`)?.focus()});
    el('canvasPaper').onchange=e=>api.paper(e.target.value);el('paperOrientation').onclick=()=>api.orientation();el('editHandles').onchange=paint;el('canvasGrid').onchange=paint;el('fitPaper').onclick=fitView;
    el('directEditor').onsubmit=event=>{event.preventDefault();const value=Number(el('directValue').value);if(!Number.isFinite(value)||el('directValue').value==='')return;api.edit(selection,api.from(value));svg.querySelector(`[data-key="${selection}"]`)?.focus()};el('closeDirect').onclick=()=>{selection=null;paint()};
    el('fitA4').onclick=()=>api.fitPaper();
    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&dragging)end({pointerId:dragging.pointer},true);else if(event.key==='Escape'&&selection){selection=null;paint()}});
  }
  return{init,render,paint,fitView,setZoom,getZoom:()=>zoom,unitSize:size};
})();
